//! Readiness of the configured units. systemd orders `adb-wan.service`
//! after them (the `install` drop-in), so this only checks and logs.

use crate::context::Ctx;

/// `After=` drop-in that orders the service after the readiness units.
/// Only ordering: `Wants=` would start LAN services this program must not touch.
pub fn drop_in(units: &[String]) -> String {
    format!(
        "# Generated by `adb-wan install` from [readiness] units in config.toml.\n\
         [Unit]\n\
         After={}\n",
        units.join(" ")
    )
}

/// Logs any readiness unit that is not active. Not fatal: recovery acts on
/// the phone only and never on these services.
pub fn check_ready(ctx: &Ctx<'_>) {
    let inactive: Vec<String> = ctx
        .config
        .readiness
        .units
        .iter()
        .filter(|unit| !matches!(ctx.host.unit_active(unit), Ok(true)))
        .cloned()
        .collect();
    if inactive.is_empty() {
        ctx.log.info("readiness units active");
    } else {
        ctx.log.warn(format_args!(
            "readiness units not active: {}; continuing (only the phone is touched)",
            inactive.join(" ")
        ));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn drop_in_only_orders() {
        let text = drop_in(&["NetworkManager.service".into(), "lan-dns.service".into()]);
        assert!(text.contains("After=NetworkManager.service lan-dns.service\n"));
        assert!(!text.contains("Wants="));
        assert!(!text.contains("Requires="));
    }
}
